    public DevGramRowEditActivity(DevGramStudioActivity.Draft draft,JSONObject row,Runnable changed,Runnable deleted){this.draft=draft;this.row=row;mediaType=row.optInt("mediaType");this.changed=changed;this.deleted=deleted;if(!row.has("rowType"))try{row.put("rowType",row.optString("type").equals("music")?0:DevGramProfileRowSpec.type(row));}catch(Exception ignored){}}
    public static void show(BaseFragment host,DevGramStudioActivity.Draft draft,JSONObject row,Runnable changed,Runnable deleted){if(!DevGramAppearanceAccess.check(host,"profile.blocks"))return;DevGramRowEditActivity editor=new DevGramRowEditActivity(draft,row,changed,deleted);editor.setCurrentAccount(host.getCurrentAccount());host.showAsSheet(editor,new BaseFragment.BottomSheetParams());}
    private final Runnable accessChanged=()->{boolean next=allowed();if(next!=policyAllowed||!DevGramProfileCustomization.enabled()||getUserConfig().getClientUserId()!=owner){policyAllowed=next;live.run();}};
    private String t(String value){return DevGramLocale.text(value);}private int type(){return DevGramProfileRowSpec.type(row);}private String feature(){return type()==10&&mediaType==1?"profile.blocks.media.animated":DevGramProfileRowSpec.feature(type());}
    @Override public boolean onFragmentCreate(){if(!super.onFragmentCreate())return false;getNotificationCenter().addObserver(this,NotificationCenter.articleClosed);return true;}
    @Override public void didReceivedNotification(int id,int account,Object... args){if(id==NotificationCenter.articleClosed&&pendingAuthorization){authorizationUntil=Math.min(authorizationUntil,android.os.SystemClock.elapsedRealtime()+15000);refreshConnection(true);}}
    private boolean allowed(){return !closed&&getUserConfig().getClientUserId()==owner&&DevGramAppearanceAccess.allowed(this,"profile.blocks")&&(type()==10?(DevGramAppearanceAccess.allowed(this,"profile.blocks.media")||DevGramAppearanceAccess.allowed(this,"profile.blocks.media.animated")):DevGramAppearanceAccess.allowed(this,feature()));}
    @Override public View createView(Context context){owner=getUserConfig().getClientUserId();actionBar.setTitle(t("Изменить строку"));actionBar.setBackButtonImage(R.drawable.ic_ab_back);actionBar.setActionBarMenuOnItemClick(new ActionBar.ActionBarMenuOnItemClick(){public void onItemClick(int id){if(id==-1)finishFragment();}});preview=new FrameLayout(context);list=new UniversalRecyclerView(this,this::fill,this::click,null);fragmentView=new DevGramSettingsLayout(context,actionBar,list,resourceProvider);policyAllowed=allowed();DevGramProfilePolicy.listen(accessChanged);updatePreview();return fragmentView;}
    private void put(String key,Object value){if(!allowed())return;try{row.put(key,value);notifyDraft();}catch(Exception ignored){}}
    private void notifyDraft(){draft.dirty=true;if(draft.onChanged!=null)draft.onChanged.run();if(changed!=null)changed.run();updatePreview();}
    private void updatePreview(){if(preview==null)return;preview.removeAllViews();if(allowed())preview.addView(new DevGramNativeProfileRow(getParentActivity(),currentAccount,owner,row,draft.document,resourceProvider,true),new FrameLayout.LayoutParams(-1,-2));}
    private void add(ArrayList<UItem> items,int id,String title,String value){TextSettingsCell cell=new TextSettingsCell(getParentActivity(),resourceProvider);cell.setTextAndValue(DevGramAppearanceAccess.label(this,feature(),t(title)),value,true);cell.setOnClickListener(v->{if(DevGramAppearanceAccess.check(this,feature())&&allowed())perform(id);});items.add(UItem.asCustom(cell));}
    private void check(ArrayList<UItem> items,int id,String key,String title,boolean fallback){TextCheckCell cell=new TextCheckCell(getParentActivity(),resourceProvider);cell.setTextAndCheck(DevGramAppearanceAccess.label(this,feature(),t(title)),row.optBoolean(key,fallback),true);cell.setOnClickListener(v->{if(!DevGramAppearanceAccess.check(this,feature())||!allowed())return;put(key,!row.optBoolean(key,fallback));live.run();});items.add(UItem.asCustom(cell));}
    private void header(ArrayList<UItem> items,String value){items.add(UItem.asHeader(t(value)));}private void help(ArrayList<UItem> items,String value){items.add(UItem.asShadow(t(value)));}
