        int type=type();items.add(UItem.asCustom(preview));header(items,"Вид строки");items.add(UItem.asCustom(new DevGramRowTypeSelector(getParentActivity(),this,type,next->{if(!DevGramAppearanceAccess.check(this,DevGramProfileRowSpec.feature(next)))return;connecting=false;connectionLoading=false;connectionApplyPending=false;pendingAuthorization=false;connectionGeneration++;AndroidUtilities.cancelRunOnUIThread(authorizationPoll);DevGramProfileRowSpec.type(row,next);notifyDraft();if(next==12)refreshConnection(false);live.run();})));
        if(DevGramProfileRowSpec.shows("content",type)){header(items,"Содержимое");if(DevGramProfileRowSpec.shows("title",type))add(items,1,"Подпись",row.optString("title"));if(DevGramProfileRowSpec.shows("value",type))add(items,2,"Значение",row.optString("url"));if(DevGramProfileRowSpec.shows("text",type))add(items,3,"Текст",row.optString("text"));}
