    private void refreshConnection(boolean apply){
        int selected=row.optInt("service");if(!allowed()||type()!=12||!DevGramServiceConnections.oauth(selected)||connecting)return;
        if(connectionLoading){connectionApplyPending|=apply;return;}connectionLoading=true;int request=++connectionGeneration;
        DevGramServiceConnections.request(currentAccount,selected,"status",(result,error)->{
            if(closed||request!=connectionGeneration||!allowed()||type()!=12||row.optInt("service")!=selected)return;
            connectionLoading=false;boolean applyAccount=apply||connectionApplyPending||row.optString("url").isEmpty();connectionApplyPending=false;
            if(result!=null){connectionState=result;boolean completed=pendingAuthorization&&result.optBoolean("connected")&&result.optLong("updated")!=authorizationBaseline;
                if(result.optBoolean("connected")&&(completed||!pendingAuthorization&&applyAccount))applyConnection(selected,result.optString("handle"));
                if(completed){pendingAuthorization=false;DevGramProfileIntegrations.clear();}
            }
            AndroidUtilities.cancelRunOnUIThread(authorizationPoll);
            if(pendingAuthorization&&android.os.SystemClock.elapsedRealtime()<authorizationUntil){if(resumed)AndroidUtilities.runOnUIThread(authorizationPoll,3000);}else pendingAuthorization=false;
            live.run();
        });
    }
    private void applyConnection(int service,String handle){
        if(!handle.matches("[A-Za-z0-9_.@-]{1,80}"))return;String provider=DevGramProfileRowSpec.PROVIDERS[service];JSONObject accounts=row.optJSONObject("accounts");
        if(accounts!=null&&handle.equals(accounts.optString(provider))&&handle.equals(row.optString("url")))return;
        try{accounts=accounts==null?new JSONObject():DevGramProfileDocument.copy(accounts);accounts.put(provider,handle);row.put("accounts",accounts).put("url",handle);DevGramProfileIntegrations.clear();notifyDraft();}catch(Exception ignored){}
    }
    @Override public void onResume(){super.onResume();resumed=true;refreshConnection(pendingAuthorization||row.optString("url").isEmpty());}
    @Override public void onBecomeFullyVisible(){super.onBecomeFullyVisible();refreshConnection(pendingAuthorization||row.optString("url").isEmpty());}
    @Override public void onPause(){resumed=false;AndroidUtilities.cancelRunOnUIThread(authorizationPoll);super.onPause();}
    private boolean galleryPermission(){
        if(getParentActivity()==null)return false;
        if(android.os.Build.VERSION.SDK_INT>=34&&getParentActivity().checkSelfPermission(android.Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED)==android.content.pm.PackageManager.PERMISSION_GRANTED)return true;
        String permission=android.os.Build.VERSION.SDK_INT>=33?android.Manifest.permission.READ_MEDIA_IMAGES:android.Manifest.permission.READ_EXTERNAL_STORAGE;
        return getParentActivity().checkSelfPermission(permission)==android.content.pm.PackageManager.PERMISSION_GRANTED;
    }
    private void cropImage() {
        if(!allowed()||type()!=10||getParentActivity()==null||row.optString("url").isEmpty())return;
        Context context=getParentActivity();
        String source=row.optString("url");
        DevGramProfileImageView image=new DevGramProfileImageView(context);
        image.setCrop(row);image.setRoundRadius(AndroidUtilities.dp(row.optInt("radius",16)));
        image.setImage(DevGramProfileTextures.imageUrl(source),"1200_800",null);
        image.enableCropGestures();image.setContentDescription(t("Подогнать изображение"));
        LinearLayout body=DevGramStudioControls.column(context);
        TextView hint=DevGramStudioControls.text(context,"Двигайте изображение пальцем. Разведите два пальца, чтобы приблизить нужную часть.",14,false,resourceProvider);
        hint.setPadding(AndroidUtilities.dp(22),AndroidUtilities.dp(8),AndroidUtilities.dp(22),AndroidUtilities.dp(12));body.addView(hint);
        FrameLayout frame=new FrameLayout(context){
            @Override protected void onMeasure(int widthSpec,int heightSpec){
                int width=MeasureSpec.getSize(widthSpec);
                int profileWidth=Math.max(1,(list.getWidth()>0?list.getWidth():width)-(DevGramClassicDesign.enabled()?0:AndroidUtilities.dp(24)));
                float aspect=profileWidth/(float)AndroidUtilities.dp(Math.max(80,Math.min(480,row.optInt("height",180))));
                int maxHeight=Math.max(AndroidUtilities.dp(80),(int)(AndroidUtilities.displaySize.y*.45f));
                int imageWidth=Math.max(1,Math.min(width-AndroidUtilities.dp(32),(int)(maxHeight*aspect)));
                ViewGroup.LayoutParams params=image.getLayoutParams();params.width=imageWidth;params.height=Math.max(1,Math.round(imageWidth/aspect));
                super.onMeasure(widthSpec,MeasureSpec.makeMeasureSpec(params.height+AndroidUtilities.dp(16),MeasureSpec.EXACTLY));
            }
        };
        frame.addView(image,new FrameLayout.LayoutParams(1,1,Gravity.CENTER));body.addView(frame);
        BottomSheet sheet=new BottomSheet(context,false,resourceProvider);sheet.setCanDismissWithSwipe(false);
        TextSettingsCell reset=new TextSettingsCell(context,resourceProvider);reset.setText(t("Сбросить кадрирование"),true);reset.setOnClickListener(v->image.resetCrop());body.addView(reset);
        TextSettingsCell apply=new TextSettingsCell(context,resourceProvider);apply.setText(t("Применить"),false);apply.getTextView().setTextColor(Theme.getColor(Theme.key_windowBackgroundWhiteBlueText,resourceProvider));
        apply.setOnClickListener(v->{if(allowed()&&type()==10&&source.equals(row.optString("url"))){image.saveCrop(row);notifyDraft();live.run();}sheet.dismiss();});body.addView(apply);
        sheet.setTitle(t("Подогнать изображение"));sheet.setCustomView(body);sheet.fixNavigationBarKey(Theme.key_dialogBackground);showDialog(sheet);
    }
    private void openImageGallery(){
        if(!allowed()||uploading||type()!=10||getParentActivity()==null)return;
        if(!galleryPermission()){
            String permission=android.os.Build.VERSION.SDK_INT>=33?android.Manifest.permission.READ_MEDIA_IMAGES:android.Manifest.permission.READ_EXTERNAL_STORAGE;
            String[] permissions=android.os.Build.VERSION.SDK_INT>=34?new String[]{permission,android.Manifest.permission.READ_MEDIA_VISUAL_USER_SELECTED}:new String[]{permission};
            getParentActivity().requestPermissions(permissions,GALLERY_PERMISSION);return;
        }
        PhotoAlbumPickerActivity picker=new PhotoAlbumPickerActivity(PhotoAlbumPickerActivity.SELECT_TYPE_ALL,true,false,null){
            @Override public View createView(Context context){View view=super.createView(context);ActionBarMenuItem more=actionBar.createMenu().getItem(0);if(more!=null)more.setVisibility(View.GONE);return view;}
        };
        picker.setCurrentAccount(currentAccount);picker.setMaxSelectedPhotos(1,false);picker.setAllowSearchImages(false);
        picker.setDelegate(new PhotoAlbumPickerActivity.PhotoAlbumPickerActivityDelegate(){
            @Override public void didSelectPhotos(ArrayList<SendMessagesHelper.SendingMediaInfo> photos,boolean notify,int scheduleDate){
                if(!allowed()||uploading||type()!=10||photos==null||photos.isEmpty())return;
                SendMessagesHelper.SendingMediaInfo photo=photos.get(0);if(photo.isVideo){error("Выберите изображение");return;}
                android.net.Uri uri=photo.uri;if(photo.path!=null&&!photo.path.isEmpty())uri=android.net.Uri.fromFile(new java.io.File(photo.path));
                if(uri==null){error("Не удалось загрузить изображение");return;}
                int request=++generation;uploading=true;live.run();DevGramProfileTextures.uploadGalleryPhoto(currentAccount,uri,mediaType==1?"row_animated":"row_static",(result,failure)->{
                    if(closed||request!=generation)return;uploading=false;
                    if(allowed()&&type()==10){if(result!=null&&DevGramAppearanceAccess.allowed(DevGramRowEditActivity.this,result.optInt("frames")>1?"profile.blocks.media.animated":"profile.blocks.media")){row.remove("imageFocusX");row.remove("imageFocusY");row.remove("imageScale");put("mediaType",result.optInt("frames")>1?1:0);put("url",result.optString("source"));}else error("Не удалось загрузить изображение");}live.run();
                });
            }
            @Override public void startPhotoSelectActivity(){} // External picker is hidden in this gallery.
        });
        presentFragment(picker);
    }
    @Override public void onRequestPermissionsResultFragment(int requestCode,String[] permissions,int[] results){
        super.onRequestPermissionsResultFragment(requestCode,permissions,results);
        if(requestCode==GALLERY_PERMISSION&&allowed()&&type()==10){if(galleryPermission())openImageGallery();else error("Разрешите доступ к фотографиям для выбора изображения");}
    }
    private void error(String value){if(getParentActivity()!=null)BulletinFactory.of(this).createErrorBulletin(t(value)).show();}
    @Override public void onFragmentDestroy(){closed=true;generation++;connectionGeneration++;AndroidUtilities.cancelRunOnUIThread(authorizationPoll);getNotificationCenter().removeObserver(this,NotificationCenter.articleClosed);DevGramProfilePolicy.unlisten(accessChanged);super.onFragmentDestroy();}
